<script setup lang="ts">
// Permission Registry (generated by engineering-platform frontend-enterprise-management asset)
// READ-ONLY governance surface: permission codes are declared by the platform,
// never created/edited/deleted from the UI.
import { computed, onMounted, ref } from 'vue';
import PageHeader from '../../components/PageHeader.vue';
import PageContainer from '../../components/PageContainer.vue';
import { permissionApi } from '../../api/enterprise';
import type { Permission } from '../../types/enterprise';
import { groupPermissions, domainLabel, resourceLabel, actionLabel } from '../../utils/permissionMatrix';
import { errorMessage } from '../../utils/feedback';

const permissions = ref<Permission[]>([]);
const loading = ref(false);
const error = ref<string | null>(null);
const keyword = ref('');

const groups = computed(() => groupPermissions(permissions.value));
const filteredGroups = computed(() => {
  if (!keyword.value.trim()) {
    return groups.value;
  }
  const k = keyword.value.trim().toLowerCase();
  return groups.value
    .map((g) => ({
      ...g,
      resources: g.resources
        .map((r) => ({
          ...r,
          actions: r.actions.filter(
            (a) =>
              a.permission.code.toLowerCase().includes(k) ||
              a.permission.name.toLowerCase().includes(k) ||
              resourceLabel(r.resource).toLowerCase().includes(k),
          ),
        }))
        .filter((r) => r.actions.length > 0),
    }))
    .filter((g) => g.resources.length > 0);
});

async function load(): Promise<void> {
  loading.value = true;
  error.value = null;
  try {
    permissions.value = await permissionApi.list();
  } catch (e) {
    error.value = errorMessage(e);
  } finally {
    loading.value = false;
  }
}

onMounted(load);
</script>

<template>
  <PageContainer>
    <PageHeader title="Permission Registry" description="READ ONLY — permission codes are declared by the platform and cannot be created or edited here.">
      <template #actions>
        <el-input
          v-model="keyword"
          placeholder="Search code or name"
          clearable
          style="width: 240px"
          data-testid="permission-search"
        />
      </template>
    </PageHeader>

    <el-alert
      type="info"
      :closable="false"
      title="System-defined registry"
      description="Permissions are part of the platform's security model. Changes require a platform release, not a UI edit."
      class="registry-banner"
    />

    <div v-if="error" class="registry-error">
      <el-tag type="danger">{{ error }}</el-tag>
      <el-button size="small" @click="load">Retry</el-button>
    </div>

    <div v-else v-loading="loading" data-testid="permission-registry">
      <section v-for="group in filteredGroups" :key="group.domain" class="registry-domain" data-testid="permission-domain">
        <h3 class="registry-domain-title">{{ domainLabel(group.domain) }}</h3>
        <el-table :data="group.resources" data-testid="permission-table">
          <el-table-column label="Resource" width="180">
            <template #default="{ row }">{{ resourceLabel(row.resource) }}</template>
          </el-table-column>
          <el-table-column label="Actions">
            <template #default="{ row }">
              <el-tag
                v-for="a in row.actions"
                :key="a.permission.id"
                size="small"
                type="info"
                class="permission-tag"
                :data-testid="'permission-' + (a.permission.code)"
              >
                {{ actionLabel(a.action) }}
              </el-tag>
            </template>
          </el-table-column>
        </el-table>
      </section>
    </div>
  </PageContainer>
</template>

