  display: flex;
  align-items: center;
  gap: var(--ep-space-3);
}
.registry-domain {
  margin-bottom: var(--ep-space-6);
}
.registry-domain-title {
  margin: 0 0 var(--ep-space-3);
  font-size: var(--ep-font-size-lg);
  color: var(--ep-color-primary);
}
.permission-tag {
  margin-right: var(--ep-space-2);
  margin-bottom: var(--ep-space-1);
}
</style>
